`, "",{"version":3,"sources":["webpack://./src/components/EntityForm.vue"],"names":[],"mappings":";AAqQA;CACA,aAAA;CACA,sBAAA;CACA,SAAA;AACA;AAEA;CACA,aAAA;CACA,sBAAA;CACA,QAAA;AACA;AAEA;CACA,eAAA;CACA,gBAAA;CACA,oCAAA;AACA;AAEA;CACA,yBAAA;AACA;AAEA;CACA,kBAAA;CACA,QAAA;CACA,wCAAA;CACA,YAAA;CACA,aAAA;CACA,mBAAA;CACA,uBAAA;CACA,WAAA;AACA","sourcesContent":["<template>\n\t<form ref=\"form\" class=\"cm-entity-form\" @submit.prevent=\"submit\">\n\t\t<div v-if=\"loadingReferences\" class=\"cm-entity-form__loading\">\n\t\t\t<NcLoadingIcon :size=\"32\" />\n\t\t</div>\n\t\t<div v-for=\"field in fields\" :key=\"field.key\" class=\"cm-entity-form__field\">\n\t\t\t<label :for=\"`field-${field.key}`\">\n\t\t\t\t{{ field.label }}\n\t\t\t\t<span v-if=\"field.required\" class=\"cm-entity-form__required\">*</span>\n\t\t\t</label>\n\n\t\t\t<NcTextField v-if=\"field.type === 'text' || field.type === 'number'\"\n\t\t\t\t:id=\"`field-${field.key}`\"\n\t\t\t\tv-model=\"form[field.key]\"\n\t\t\t\t:type=\"field.type\"\n\t\t\t\t:required=\"field.required\"\n\t\t\t\t:label=\"field.label\"\n\t\t\t\t:show-trailing-button=\"false\" />\n\n\t\t\t<NcDateTimePicker v-else-if=\"field.type === 'date'\"\n\t\t\t\t:id=\"`field-${field.key}`\"\n\t\t\t\tv-model=\"form[field.key]\"\n\t\t\t\t:type=\"'date'\"\n\t\t\t\t:format=\"dateFormat\"\n\t\t\t\tvalue-type=\"YYYY-MM-DD\"\n\t\t\t\t:append-to-body=\"true\"\n\t\t\t\t:required=\"field.required\"\n\t\t\t\t:label=\"field.label\" />\n\n\t\t\t<NcTextArea v-else-if=\"field.type === 'textarea'\"\n\t\t\t\t:id=\"`field-${field.key}`\"\n\t\t\t\tv-model=\"form[field.key]\"\n\t\t\t\t:required=\"field.required\"\n\t\t\t\t:label=\"field.label\" />\n\n\t\t\t<NcSelect v-else-if=\"field.type === 'select'\"\n\t\t\t\t:id=\"`field-${field.key}`\"\n\t\t\t\tv-model=\"form[field.key]\"\n\t\t\t\t:options=\"field.options\"\n\t\t\t\t:label=\"field.optionLabel || 'label'\"\n\t\t\t\t:reduce=\"field.optionValue ? v => v[field.optionValue] : v => v\"\n\t\t\t\t:required=\"field.required\"\n\t\t\t\t:disabled=\"field.disabled\"\n\t\t\t\t:placeholder=\"field.label\" />\n\n\t\t\t<NcCheckboxRadioSwitch v-else-if=\"field.type === 'checkbox'\"\n\t\t\t\t:id=\"`field-${field.key}`\"\n\t\t\t\t:checked.sync=\"form[field.key]\">\n\t\t\t\t{{ field.label }}\n\t\t\t</NcCheckboxRadioSwitch>\n\t\t</div>\n\t</form>\n</template>\n\n<script>\nimport { NcTextField, NcTextArea, NcSelect, NcLoadingIcon, NcDateTimePicker, NcCheckboxRadioSwitch } from '@nextcloud/vue'\nimport { useUiStore } from '../stores/ui.js'\nimport { useCasesStore, usePaymentsStore, useUpdatesStore, useCitiesStore, useCaseTypesStore, useUpdateTypesStore, useTransfersStore } from '../stores/entities.js'\nimport { post } from '../services/api.js'\nimport { translate as t } from '@nextcloud/l10n'\nimport { isValidDate, getDateFormatForLocale } from '../utils/date.js'\n\nexport default {\n\tname: 'EntityForm',\n\tcomponents: {\n\t\tNcTextField,\n\t\tNcTextArea,\n\t\tNcSelect,\n\t\tNcLoadingIcon,\n\t\tNcDateTimePicker,\n\t\tNcCheckboxRadioSwitch,\n\t},\n\tprops: {\n\t\tmode: { type: String, required: true },\n\t\tentityType: { type: String, required: true },\n\t\tentity: { type: Object, default: null },\n\t},\n\tsetup() {\n\t\tconst ui = useUiStore()\n\t\tconst stores = {\n\t\t\tcc_Case: useCasesStore(),\n\t\t\tcc_Payment: usePaymentsStore(),\n\t\t\tcc_Update: useUpdatesStore(),\n\t\t\tcc_City: useCitiesStore(),\n\t\t\tcc_CaseType: useCaseTypesStore(),\n\t\t\tcc_UpdateType: useUpdateTypesStore(),\n\t\t\tcc_Transfer: useTransfersStore(),\n\t\t}\n\t\treturn { ui, stores, t }\n\t},\n\tdata() {\n\t\treturn {\n\t\t\tform: {},\n\t\t\tloadingReferences: false,\n\t\t\tusers: [],\n\t\t}\n\t},\n\tcomputed: {\n\t\tdateFormat() {\n\t\t\treturn getDateFormatForLocale()\n\t\t},\n\t\tstore() {\n\t\t\treturn this.stores[this.entityType]\n\t\t},\n\t\tsubmitLabel() {\n\t\t\treturn this.mode === 'add' ? t('charity', 'Create') : t('charity', 'Save Changes')\n\t\t},\n\t\tpaymentTypeOptions() {\n\t\t\tconst base = [{ label: 'Payment' }, { label: 'Receipt' }, { label: 'Asset Purchase' }]\n\t\t\tif (!this.form.caseId) {\n\t\t\t\tbase.push({ label: 'Expense Payment' })\n\t\t\t}\n\t\t\treturn base\n\t\t},\n\t\tfields() {\n\t\t\tswitch (this.entityType) {\n\t\t\tcase 'cc_Case':\n\t\t\t\treturn [\n\t\t\t\t\t{ key: 'firstName', label: t('charity', 'First Name'), type: 'text', required: true },\n\t\t\t\t\t{ key: 'lastName', label: t('charity', 'Last Name'), type: 'text', required: true },\n\t\t\t\t\t{ key: 'idNumber', label: t('charity', 'ID Number'), type: 'text' },\n\t\t\t\t\t{ key: 'caseTypeId', label: t('charity', 'Case Type'), type: 'select', options: this.stores.cc_CaseType?.items || [], optionLabel: 'title', optionValue: 'id' },\n\t\t\t\t\t{ key: 'dateAdded', label: t('charity', 'Date Added'), type: 'date' },\n\t\t\t\t\t{ key: 'dob', label: t('charity', 'Date of Birth'), type: 'date' },\n\t\t\t\t\t{ key: 'referredBy', label: t('charity', 'Referred By'), type: 'select', options: this.users, optionLabel: 'displayName', optionValue: 'uid', required: true },\n\t\t\t\t\t{ key: 'cityId', label: t('charity', 'City'), type: 'select', options: this.stores.cc_City?.items || [], optionLabel: 'title', optionValue: 'id', required: true },\n\t\t\t\t\t{ key: 'town', label: t('charity', 'Town'), type: 'text' },\n\t\t\t\t\t{ key: 'location', label: t('charity', 'Location'), type: 'text' },\n\t\t\t\t\t{ key: 'dependants', label: t('charity', 'Dependants'), type: 'number' },\n\t\t\t\t\t{ key: 'description', label: t('charity', 'Description'), type: 'textarea' },\n\t\t\t\t\t{ key: 'recommendation', label: t('charity', 'Recommendation'), type: 'textarea' },\n\t\t\t\t\t{ key: 'monthly', label: t('charity', 'Monthly contribution'), type: 'checkbox' },\n\t\t\t\t]\n\t\t\tcase 'cc_Payment':\n\t\t\t\treturn [\n\t\t\t\t\t{ key: 'caseId', label: t('charity', 'Case'), type: 'select', options: [{ _displayLabel: t('charity', 'None') }, ...(this.stores.cc_Case?.items || []).map(c => ({ ...c, _displayLabel: String(c.id).padStart(10, '0') }))], optionLabel: '_displayLabel', optionValue: 'id' },\n\t\t\t\t\t{ key: 'paymentDate', label: t('charity', 'Payment Date'), type: 'date', required: true },\n\t\t\t\t\t{ key: 'paymentType', label: t('charity', 'Payment Type'), type: 'select', options: this.paymentTypeOptions, optionLabel: 'label', optionValue: 'label' },\n\t\t\t\t\t{ key: 'paymentAmount', label: t('charity', 'Amount'), type: 'number', required: true },\n\t\t\t\t\t{ key: 'paymentReference', label: t('charity', 'Payment Reference'), type: 'text' },\n\t\t\t\t\t{ key: 'paidBy', label: t('charity', 'Cashbook'), type: 'select', options: this.users, optionLabel: 'displayName', optionValue: 'uid' },\n\t\t\t\t\t{ key: 'description', label: t('charity', 'Description'), type: 'textarea' },\n\t\t\t\t]\n\t\t\tcase 'cc_Update':\n\t\t\t\treturn [\n\t\t\t\t\t{ key: 'caseId', label: t('charity', 'Case'), type: 'select', options: (this.stores.cc_Case?.items || []).map(c => ({ ...c, _displayLabel: String(c.id).padStart(10, '0') })), optionLabel: '_displayLabel', optionValue: 'id', required: true },\n\t\t\t\t\t{ key: 'updateDate', label: t('charity', 'Update Date'), type: 'date', required: true },\n\t\t\t\t\t{ key: 'updateTypeId', label: t('charity', 'Update Type'), type: 'select', options: this.stores.cc_UpdateType?.items || [], optionLabel: 'title', optionValue: 'id' },\n\t\t\t\t\t{ key: 'updateBy', label: t('charity', 'Updated By'), type: 'select', options: this.users, optionLabel: 'displayName', optionValue: 'uid' },\n\t\t\t\t\t{ key: 'description', label: t('charity', 'Description'), type: 'textarea' },\n\t\t\t\t]\n\t\t\tcase 'cc_City':\n\t\t\t\treturn [\n\t\t\t\t\t{ key: 'title', label: t('charity', 'Title'), type: 'text', required: true },\n\t\t\t\t]\n\t\t\tcase 'cc_CaseType':\n\t\t\t\treturn [\n\t\t\t\t\t{ key: 'title', label: t('charity', 'Title'), type: 'text', required: true },\n\t\t\t\t]\n\t\t\tcase 'cc_UpdateType':\n\t\t\t\treturn [\n\t\t\t\t\t{ key: 'title', label: t('charity', 'Title'), type: 'text', required: true },\n\t\t\t\t]\n\t\t\tcase 'cc_Transfer':\n\t\t\t\treturn [\n\t\t\t\t\t{ key: 'transferDate', label: t('charity', 'Transfer Date'), type: 'date', required: true },\n\t\t\t\t\t{ key: 'ref', label: t('charity', 'Reference'), type: 'text' },\n\t\t\t\t\t{ key: 'amount', label: t('charity', 'Amount'), type: 'number', required: true },\n\t\t\t\t\t{ key: 'paidFrom', label: t('charity', 'Paid From'), type: 'select', options: this.users, optionLabel: 'displayName', optionValue: 'uid', required: true },\n\t\t\t\t\t{ key: 'paidTo', label: t('charity', 'Paid To'), type: 'select', options: this.users, optionLabel: 'displayName', optionValue: 'uid', required: true },\n\t\t\t\t\t{ key: 'description', label: t('charity', 'Description'), type: 'textarea' },\n\t\t\t\t]\n\t\t\tdefault:\n\t\t\t\treturn []\n\t\t\t}\n\t\t},\n\t},\n\twatch: {\n\t\tentity: {\n\t\t\timmediate: true,\n\t\t\thandler(entity) {\n\t\t\t\tthis.form = entity ? { ...entity } : {}\n\t\t\t\tthis.fields.forEach(field => {\n\t\t\t\t\tif (this.form[field.key] === undefined) {\n\t\t\t\t\t\t// Textareas should default to an empty string so v-model/bindings\n\t\t\t\t\t\t// always treat them as a controlled string input.\n\t\t\t\t\t\tif (field.type === 'textarea') this.$set(this.form, field.key, '')\n\t\t\t\t\t\telse if (field.type === 'checkbox') this.$set(this.form, field.key, false)\n\t\t\t\t\t\telse this.$set(this.form, field.key, null)\n\t\t\t\t\t}\n\t\t\t\t})\n\t\t\t},\n\t\t},\n\t\t'form.caseId'(newVal, oldVal) {\n\t\t\tif (newVal && !oldVal && this.form.paymentType === 'Expense Payment') {\n\t\t\t\tthis.form.paymentType = null\n\t\t\t}\n\t\t},\n\t},\n\tasync mounted() {\n\t\tthis.loadingReferences = true\n\t\tawait this.loadReferenceStores()\n\t\tthis.loadingReferences = false\n\t},\n\tmethods: {\n\t\tasync loadReferenceStores() {\n\t\t\tconst needed = {\n\t\t\t\tcc_Case: ['cc_CaseType', 'cc_City'],\n\t\t\t\tcc_Payment: ['cc_Case'],\n\t\t\t\tcc_Update: ['cc_Case', 'cc_UpdateType'],\n\t\t\t\tcc_City: [],\n\t\t\t\tcc_CaseType: [],\n\t\t\t\tcc_UpdateType: [],\n\t\t\t\tcc_Transfer: [],\n\t\t\t}[this.entityType] || []\n\t\t\tawait Promise.all(needed.map(async key => {\n\t\t\t\tif (this.stores[key]) {\n\t\t\t\t\tawait this.stores[key].fetchAll()\n\t\t\t\t}\n\t\t\t}))\n\t\t\tif (this.entityType === 'cc_Case' || this.entityType === 'cc_Payment' || this.entityType === 'cc_Update' || this.entityType === 'cc_Transfer') {\n\t\t\t\ttry {\n\t\t\t\t\tconst result = await post('/team/usersByGroup', { params: { group: 'Charity Field' } })\n\t\t\t\t\tthis.users = result || []\n\t\t\t\t} catch (e) {\n\t\t\t\t\tconsole.error('Failed to load users', e)\n\t\t\t\t\tthis.users = []\n\t\t\t\t}\n\t\t\t}\n\t\t},\n\t\tasync submit() {\n\t\t\tconst payload = { ...this.form }\n\t\t\tconst dateFields = this.fields.filter(f => f.type === 'date')\n\t\t\tfor (const field of dateFields) {\n\t\t\t\tconst value = payload[field.key]\n\t\t\t\tif (!value && field.required) {\n\t\t\t\t\talert(t('charity', '{field} is required', { field: field.label }))\n\t\t\t\t\treturn\n\t\t\t\t}\n\t\t\t\tif (value && !isValidDate(value)) {\n\t\t\t\t\talert(t('charity', '{field} is not a valid date', { field: field.label }))\n\t\t\t\t\treturn\n\t\t\t\t}\n\t\t\t}\n\t\t\ttry {\n\t\t\t\tif (this.mode === 'add') {\n\t\t\t\t\tawait this.store.create(payload)\n\t\t\t\t} else {\n\t\t\t\t\tawait this.store.update(payload.id, payload)\n\t\t\t\t}\n\t\t\t\tthis.ui.closeSlidePanel()\n\t\t\t} catch (err) {\n\t\t\t\tconsole.error(err)\n\t\t\t\talert(err.message)\n\t\t\t}\n\t\t},\n\t},\n}\n</script>\n\n<style scoped>\n.cm-entity-form {\n\tdisplay: flex;\n\tflex-direction: column;\n\tgap: 20px;\n}\n\n.cm-entity-form__field {\n\tdisplay: flex;\n\tflex-direction: column;\n\tgap: 6px;\n}\n\n.cm-entity-form__field label {\n\tfont-size: 14px;\n\tfont-weight: 600;\n\tcolor: var(--color-text-maxcontrast);\n}\n\n.cm-entity-form__required {\n\tcolor: var(--color-error);\n}\n\n.cm-entity-form__loading {\n\tposition: absolute;\n\tinset: 0;\n\tbackground: var(--color-main-background);\n\topacity: 0.8;\n\tdisplay: flex;\n\talign-items: center;\n\tjustify-content: center;\n\tz-index: 10;\n}\n</style>\n"],"sourceRoot":""}]);
